      const { title, description } = req.body || {};
      const safeTitle = typeof title === 'string' && title.trim() ? title.trim() : null;
      if (!safeTitle) return res.status(400).json({ error: 'title is required' });

      const question = await Question.create({
        title: safeTitle,
        description: typeof description === 'string' ? description : '',
        allowed_libraries: []
      });

      // Create minimal spec so the question is editable immediately.
      await TestSpec.create({
        question_id: question.id,
        spec_json: {
          version: '1.0',
          viewports: [
            { name: 'desktop', width: 1366, height: 768 },
            { name: 'mobile', width: 390, height: 844 }
          ],
          rubric: { html: 20, css: 35, js: 35, visual: 10 },
          tests: { dom: [], css: [], interactions: [] }
        }
      });

      // Provide starter files so Practice Workspace can load the question immediately.
      await QuestionFile.create({ question_id: question.id, type: 'html', filename: 'index.html', content: DEFAULT_STARTER_HTML });
      await QuestionFile.create({ question_id: question.id, type: 'css', filename: 'styles.css', content: '' });
      await QuestionFile.create({ question_id: question.id, type: 'js', filename: 'script.js', content: '' });

      res.json({
        question,
        baseline: {
          queued: false,
          version: null,
          job_id: null,
          auto_filled: false
        }
      });
    } catch (error) {
      console.error('createQuestion failed:', error);
      // Sequelize often collapses this to "Validation error"; return more context for debugging.
      const details = Array.isArray(error?.errors) ? error.errors.map(e => e.message) : undefined;
      res.status(500).json({ error: error.message, details });
    }
  },
  getQuestionDraft: async (req, res) => {
    try {
      const { questionId } = req.params;

      const question = await Question.findByPk(questionId);
      if (!question) return res.status(404).json({ error: 'Question not found' });

      const spec = await TestSpec.findOne({ where: { question_id: questionId } });
      const files = await QuestionFile.findAll({ where: { question_id: questionId } });

      res.json({
        question,
        testSpec: spec ? spec.spec_json : null,
        files
      });
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
  },
  saveQuestionDraft: async (req, res) => {
    try {
      const { questionId } = req.params;
      const {
        title,
        description,
        allowed_libraries,
        starter_html,
        starter_css,
        starter_js,
        spec_json
      } = req.body || {};

      const question = await Question.findByPk(questionId);
      if (!question) return res.status(404).json({ error: 'Question not found' });

      await question.update({
        title: typeof title === 'string' && title.trim() ? title.trim() : question.title,
        description: typeof description === 'string' ? description : question.description,
        allowed_libraries: Array.isArray(allowed_libraries) ? allowed_libraries : question.allowed_libraries
      });

      const upsertFile = async (type, filename, content) => {
        if (typeof content !== 'string') return;
        const existing = await QuestionFile.findOne({ where: { question_id: questionId, type } });
        if (existing) {
          await existing.update({ filename, content });
        } else {
          await QuestionFile.create({ question_id: questionId, type, filename, content });
        }
      };

      await upsertFile('html', 'index.html', starter_html);
      await upsertFile('css', 'styles.css', starter_css);
      await upsertFile('js', 'script.js', starter_js);

      let baseline = {
        queued: false,
        version: null,
        jobId: null,
        autoFilled: false
      };

      if (spec_json && typeof spec_json === 'object') {
        const preparedBaseline = prepareAutoBaselineSpec(spec_json, {
          html: starter_html,
          css: starter_css,
          js: starter_js
        });
        const existingSpec = await TestSpec.findOne({ where: { question_id: questionId } });
        if (existingSpec) {
          await existingSpec.update({ spec_json: preparedBaseline.spec });
        } else {
          await TestSpec.create({ question_id: questionId, spec_json: preparedBaseline.spec });
        }

        const currentVersion = await resolveCurrentBaselineVersion(questionId);
        if (preparedBaseline.ready && currentVersion === 0) {
          const nextVersion = currentVersion + 1;
          const job = await enqueueBaseline(questionId, nextVersion);
          baseline = {
            queued: true,
            version: nextVersion,
            jobId: job?.id || null,
            autoFilled: preparedBaseline.autoFilled
          };
        } else {
          baseline = {
            queued: false,
            version: currentVersion || null,
            jobId: null,
            autoFilled: preparedBaseline.autoFilled
          };
        }
      }

      res.json({
        success: true,
        baseline: {
          queued: baseline.queued,
          version: baseline.version,
          job_id: baseline.jobId,
          auto_filled: baseline.autoFilled
        }
      });
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
  }
};

const fs = require('fs');
const path = require('path');
const { Baseline } = require('../models');
const { enqueueBaseline } = require('./queueService');

function normalizeCode(value) {
  return typeof value === 'string' ? value : '';
}

function hasExplicitBaseline(spec = {}) {
  const baseline = spec?.baseline;
  if (!baseline || typeof baseline !== 'object') return false;

  return ['html', 'css', 'js'].some((key) => normalizeCode(baseline[key]).trim().length > 0);
}

function hasMeaningfulFallback(files = {}) {
  const html = normalizeCode(files?.html);
  const css = normalizeCode(files?.css);
  const js = normalizeCode(files?.js);

  if (css.trim().length > 0 || js.trim().length > 0) return true;

  const compactHtml = html.replace(/\s+/g, ' ').trim().toLowerCase();
  if (!compactHtml) return false;
  if (compactHtml.includes('start styling here')) return false;

  return compactHtml.length > 0;
}

function prepareAutoBaselineSpec(spec = {}, fallbackFiles = {}) {
  const nextSpec = spec && typeof spec === 'object' ? { ...spec } : {};

  if (hasExplicitBaseline(nextSpec)) {
    return {
      spec: nextSpec,
      ready: true,
      autoFilled: false
    };
  }

  if (!hasMeaningfulFallback(fallbackFiles)) {
    return {
      spec: nextSpec,
      ready: false,
      autoFilled: false
    };
  }

  nextSpec.baseline = {
    html: normalizeCode(fallbackFiles?.html),
    css: normalizeCode(fallbackFiles?.css),
    js: normalizeCode(fallbackFiles?.js)
  };

  return {
    spec: nextSpec,
    ready: true,
    autoFilled: true
  };
}

async function resolveCurrentBaselineVersion(questionId) {
  const questionIdNum = Number(questionId);
  if (!questionIdNum) return 0;

  const currentMaxDb = await Baseline.max('version', { where: { question_id: questionIdNum } });

  let currentMaxFs = 0;
  try {
    const baseDir = path.resolve(__dirname, '..', '..', '..', 'artifacts', 'baselines', `q${questionIdNum}`);
    if (fs.existsSync(baseDir)) {
      const entries = fs.readdirSync(baseDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        const match = /^v(\d+)$/i.exec(entry.name);
        if (match) currentMaxFs = Math.max(currentMaxFs, Number(match[1]) || 0);
      }
    }
  } catch (_) {
    // Ignore artifact volume read failures.
  }

  return Math.max(Number(currentMaxDb) || 0, currentMaxFs);
}

async function resolveNextBaselineVersion(questionId) {
  const current = await resolveCurrentBaselineVersion(questionId);
  return current + 1;
}

async function queueInitialBaselineIfReady(questionId, spec = {}, fallbackFiles = {}) {
  const prepared = prepareAutoBaselineSpec(spec, fallbackFiles);
  const currentVersion = await resolveCurrentBaselineVersion(questionId);

  if (!prepared.ready || currentVersion > 0) {
    return {
      queued: false,
      version: currentVersion || null,
      jobId: null,
      autoFilled: prepared.autoFilled,
      spec: prepared.spec
    };
  }

  const nextVersion = currentVersion + 1;
  const job = await enqueueBaseline(questionId, nextVersion);

  return {
    queued: true,
    version: nextVersion,
    jobId: job?.id || null,
    autoFilled: prepared.autoFilled,
    spec: prepared.spec
  };
}

module.exports = {
  prepareAutoBaselineSpec,
  resolveCurrentBaselineVersion,
  resolveNextBaselineVersion,
  queueInitialBaselineIfReady
};

