          ok: true,
          json: () => Promise.resolve({ submission_id: 'sub-123', run_id: 'run-123' })
        });
      }
      return Promise.reject(new Error('not found'));
    });

    let sseErrorCallback;
    class MockEventSourceError {
      constructor(url) {
        this.url = url;
      }
