      </section>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Play, CheckCircle2, AlertCircle, Maximize2, RotateCcw, Loader2, Sparkles, Server, Check } from 'lucide-react';
import * as Tabs from '@radix-ui/react-tabs';
import { motion, AnimatePresence } from 'framer-motion';
import CodeEditor from '../components/workspace/CodeEditor';
import PreviewFrame from '../components/workspace/PreviewFrame';
import QuestionPanel from '../components/workspace/QuestionPanel';
import { cn } from '../utils/utils';
import { useToast } from '../components/ui/use-toast';
import { buildPreviewDocument } from '../components/workspace/previewDocument';

const EVALUATION_STAGES = [
  { id: 'package', label: 'Packaging submission', duration: 600 },
  { id: 'sandbox', label: 'Launching headless sandbox', duration: 800 },
  { id: 'dom', label: 'Running DOM & CSS assertions', duration: 1200 },
  { id: 'interaction', label: 'Simulating user interactions', duration: 1000 },
  { id: 'visual', label: 'Computing visual diff heatmaps', duration: 1500 },
  { id: 'ai', label: 'Generating AI feedback insights', duration: 1100 },
  { id: 'score', label: 'Finalizing score rubric', duration: 500 }
];

export default function StudentDashboard() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState('html');
  const [questions, setQuestions] = useState([]);
  const [selectedQuestionId, setSelectedQuestionId] = useState(null);
  const [questionDetails, setQuestionDetails] = useState(null);
  const [questionsLoading, setQuestionsLoading] = useState(true);
  const [questionLoading, setQuestionLoading] = useState(true);

  const [starterCode, setStarterCode] = useState({ html: '', css: '', js: '' });
  const [code, setCode] = useState({ html: '', css: '', js: '' });
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [evalStageIndex, setEvalStageIndex] = useState(-1);
  const [activeSubmissionId, setActiveSubmissionId] = useState(null);
  const [previewUrl, setPreviewUrl] = useState('');

  const previewDoc = useMemo(() => buildPreviewDocument({ html: code.html, css: code.css, js: code.js }), [code]);

  useEffect(() => {
    const blob = new Blob([previewDoc], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    setPreviewUrl(url);

    return () => {
      URL.revokeObjectURL(url);
    };
  }, [previewDoc]);

  const openPreviewInNewTab = () => {
    if (!previewUrl) {
      toast({ title: 'Preview Not Ready', description: 'The preview is still being prepared.', variant: 'destructive' });
      return;
    }

    const w = window.open(previewUrl, '_blank');
    if (!w) {
      toast({ title: 'Popup Blocked', description: 'Allow popups to open the full preview.', variant: 'destructive' });
      return;
    }
  };

  useEffect(() => {
    let cancelled = false;
    async function loadQuestions() {
      setQuestionsLoading(true);
      try {
        const res = await fetch('/api/questions');
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.error || 'Failed to load questions');
        if (cancelled) return;
        const qs = Array.isArray(data.questions) ? data.questions : [];
        setQuestions(qs);
        const fromUrl = searchParams.get('question');
        const desired = fromUrl != null ? Number(fromUrl) : null;
        if (qs.length > 0) {
          setSelectedQuestionId((prev) => {
            if (desired && qs.some((x) => Number(x.id) === desired)) return desired;
            return prev == null ? qs[0].id : prev;
          });
        }
      } catch (e) {
        toast({ title: 'Load Failed', description: e?.message || 'Could not load questions.', variant: 'destructive' });
      } finally {
        if (!cancelled) setQuestionsLoading(false);
      }
    }
    loadQuestions();
    return () => { cancelled = true; };
  }, [toast, searchParams]);

  useEffect(() => {
    let cancelled = false;
    async function loadQuestionDetails() {
      if (!selectedQuestionId) return;
      setQuestionLoading(true);
      try {
        const res = await fetch(`/api/questions/${selectedQuestionId}`);
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.error || 'Failed to load question');
        if (cancelled) return;
        setQuestionDetails(data);
        const files = Array.isArray(data.files) ? data.files : [];
        const next = {
          html: files.find((f) => f.type === 'html')?.content ?? '',
          css: files.find((f) => f.type === 'css')?.content ?? '',
          js: files.find((f) => f.type === 'js')?.content ?? ''
        };
        setStarterCode(next);
        setCode(next);
      } catch (e) {
        toast({ title: 'Load Failed', description: e?.message || 'Could not load question.', variant: 'destructive' });
      } finally {
        if (!cancelled) setQuestionLoading(false);
      }
    }
    loadQuestionDetails();
    return () => { cancelled = true; };
  }, [selectedQuestionId, toast]);

  const question = (() => {
    const q = questionDetails?.question || {};
    const spec = questionDetails?.testSpec || {};
    const domHints = Array.isArray(spec?.tests?.dom) ? spec.tests.dom.map((t) => t.hint).filter(Boolean) : [];
    const cssHints = Array.isArray(spec?.tests?.css) ? spec.tests.css.map((t) => t.hint).filter(Boolean) : [];
    const requirements = [...domHints, ...cssHints].filter(Boolean).slice(0, 6);
    return {
      title: q.title || 'Practice Workspace',
      difficulty: spec?.difficulty || 'Medium',
      description: q.description || '',
      requirements: requirements.length > 0 ? requirements : ["Complete the UI requirements", "Match layout and hover states", "Ensure click interaction works"]
    };
  })();

  const handleRunTests = async () => {
    if (!selectedQuestionId) {
      toast({ title: 'No Question Selected', description: 'Please select a question first.', variant: 'destructive' });
      return;
    }
      setIsEvaluating(true);
      setEvalStageIndex(0);
      setActiveSubmissionId(null);

      try {
      const res = await fetch('/api/submissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          question_id: selectedQuestionId,
          student_id: 1,  // Using Demo Student ID 1
          html_content: code.html,
          css_content: code.css,
          js_content: code.js
        })
      });

      const data = await res.json();

      if (!res.ok || data.status === 'failed') {
        toast({ title: 'Validation Failed', description: data.error || data.message || 'Syntax error', variant: 'destructive' });
        setIsEvaluating(false);
        return;
      }

        const submissionId = data.submission_id;
        setActiveSubmissionId(submissionId);

        // Listen to real-time events from the BullMQ Worker
        const eventSource = new EventSource(`/api/submissions/${submissionId}/progress`);

      eventSource.onmessage = (e) => {
        const eventData = JSON.parse(e.data);

        if (eventData.status === 'completed' || eventData.status === 'failed') {
          eventSource.close();
          setEvalStageIndex(EVALUATION_STAGES.length); // Trigger UI completion state

          setTimeout(() => {
            toast({
              title: "Evaluation Completed",
              description: "Redirecting to your detailed results report...",
            });
            navigate(`/results/${submissionId}`);
          }, 1000);
        }
      };

      eventSource.onerror = () => {
        eventSource.close();
        // Fallback incase SSE stream drops
        setTimeout(() => navigate(`/results/${submissionId}`), 5000);
      };

    } catch (error) {
      toast({ title: 'Connection Error', description: 'Failed to connect to the evaluation engine.', variant: 'destructive' });
      setIsEvaluating(false);
    }
  };

  useEffect(() => {
    // Animate the pipeline stages up to the second-to-last stage while waiting for the server
    if (evalStageIndex >= 0 && evalStageIndex < EVALUATION_STAGES.length - 1) {
      const timer = setTimeout(() => {
        setEvalStageIndex(prev => prev + 1);
      }, EVALUATION_STAGES[evalStageIndex].duration);
      return () => clearTimeout(timer);
    }
    // Auto-redirect is now handled by the SSE listener when the actual backend job finishes
  }, [evalStageIndex]);

  return (
    <div className="h-full flex flex-col gap-4 relative">
      <div className="flex justify-between items-center px-2">
        <div>
          <h2 className="text-xl font-bold text-gray-900 tracking-tight">Practice Workspace</h2>
          <p className="text-sm text-gray-500">Evaluation Engine v2.0</p>
          <div className="mt-3 flex items-center gap-2">
            <span className="text-xs font-semibold text-gray-500 uppercase tracking-widest">Question</span>
            <select
              value={selectedQuestionId ?? ''}
              onChange={(e) => setSelectedQuestionId(Number(e.target.value))}
              disabled={questionsLoading}
              className="px-3 py-2 border border-gray-200 rounded-lg bg-white text-sm text-gray-700 outline-none focus:ring-2 focus:ring-emerald-100 focus:border-emerald-400 disabled:opacity-60"
            >
              {questions.map((q) => (
                <option key={q.id} value={q.id}>{q.title}</option>
              ))}
            </select>
            {questionLoading && <Loader2 size={16} className="animate-spin text-gray-400" />}
          </div>
        </div>
        <div className="flex gap-3">
           <button
             onClick={() => {
               setCode(starterCode);
               toast({ title: "Code Reset", description: "Your code has been reset to the starter template." });
             }}
             className="flex items-center gap-2 px-4 py-2 border border-gray-200 text-gray-600 bg-white hover:bg-gray-50 rounded-lg font-medium text-sm transition-colors shadow-sm"
           >
             <RotateCcw size={16} /> Reset Code
           </button>
           <button 
             onClick={handleRunTests}
             disabled={isEvaluating || !selectedQuestionId}
             className="flex items-center gap-2 px-6 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg font-medium text-sm transition-all shadow-sm shadow-emerald-600/20 disabled:opacity-70 disabled:cursor-not-allowed"
           >
             {isEvaluating ? (
               <><div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white/80"></div> Evaluating...</>
             ) : (
               <><Play size={16} fill="white" /> Submit & Evaluate</>
             )}
           </button>
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-4 min-h-[600px]">
        <div className="lg:col-span-3 bg-white rounded-xl shadow-sm border border-gray-100 flex flex-col overflow-hidden">
          <div className="bg-slate-900 text-slate-200 px-4 py-3 text-sm font-semibold border-b border-slate-800 flex items-center justify-between">
            <span>Description</span>
          </div>
          <div className="flex-1 overflow-auto">
             <QuestionPanel question={question} />
          </div>
        </div>

        <div className="lg:col-span-5 bg-slate-900 rounded-xl shadow-sm border border-slate-800 flex flex-col overflow-hidden shadow-emerald-900/5">
          <Tabs.Root value={activeTab} onValueChange={setActiveTab} className="flex flex-col h-full">
            <Tabs.List className="flex bg-slate-900 border-b border-slate-800 px-2 pt-2 gap-1">
              {['html', 'css', 'js'].map((lang) => (
                <Tabs.Trigger
                  key={lang}
                  value={lang}
                  className={cn(
                    "px-4 py-2 text-sm font-medium rounded-t-lg transition-all border border-transparent border-b-0",
                    activeTab === lang 
                      ? "bg-slate-800 text-emerald-400 border-slate-700 shadow-sm" 
                      : "text-slate-400 hover:text-slate-200 hover:bg-slate-800/50"
                  )}
                >
                  index.{lang}
                </Tabs.Trigger>
              ))}
            </Tabs.List>
            <div className="flex-1 min-h-0 bg-[#0f172a]">
              <CodeEditor 
                language={activeTab === 'js' ? 'javascript' : activeTab}
                value={code[activeTab]}
                onChange={(val) => setCode(prev => ({ ...prev, [activeTab]: val }))}
              />
            </div>
          </Tabs.Root>
        </div>

        <div className="lg:col-span-4 flex flex-col gap-4">
           <div className="flex-1 bg-white rounded-xl shadow-sm border border-gray-100 flex flex-col overflow-hidden min-h-[300px]">
             <div className="bg-slate-900 text-slate-200 px-4 py-3 text-sm font-semibold border-b border-slate-800 flex items-center justify-between">
                <span>Live Preview</span>
                <button
                  type="button"
                  onClick={openPreviewInNewTab}
                  className="text-slate-400 hover:text-white transition-colors"
                  aria-label="Open full preview in new tab"
                  title="Open full preview"
                >
                  <Maximize2 size={14} />
                </button>
             </div>
             <div className="flex-1 relative">
                <PreviewFrame html={code.html} css={code.css} js={code.js} />
             </div>
           </div>

        </div>
      </div>

      {/* Animated Live Evaluation Progress Overlay */}
      <AnimatePresence>
        {isEvaluating && (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-50 flex items-center justify-center bg-white/80 backdrop-blur-md rounded-2xl"
          >
            <motion.div 
              initial={{ scale: 0.95, y: 10 }}
              animate={{ scale: 1, y: 0 }}
              className="bg-white p-8 rounded-2xl shadow-2xl border border-gray-100 w-full max-w-md"
            >
              <div className="flex items-center gap-3 mb-6">
                 <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600">
                   {evalStageIndex >= EVALUATION_STAGES.length ? <Check size={20} className="text-emerald-500" /> : <Server size={20} className="animate-pulse" />}
                 </div>
                 <div>
                   <h3 className="font-bold text-gray-900 text-lg">Evaluation Pipeline</h3>
                   <p className="text-sm text-gray-500">
                     {activeSubmissionId ? (
                       <>Submission ID: <span className="font-mono text-xs">{activeSubmissionId}</span></>
                     ) : (
                       <>Submitting to worker poolâ€¦</>
                     )}
                   </p>
                 </div>
              </div>

              <div className="space-y-4">
                {EVALUATION_STAGES.map((stage, i) => {
                  const isActive = i === evalStageIndex;
                  const isPast = i < evalStageIndex;
                  return (
                    <div key={stage.id} className="flex flex-col gap-1.5">
                      <div className="flex justify-between items-center text-sm">
                        <span className={cn(
                          "font-medium transition-colors duration-300",
                          isActive ? "text-emerald-600" : isPast ? "text-gray-900" : "text-gray-400"
                        )}>
                          {stage.label}
                        </span>
                        {isActive && <Loader2 size={14} className="text-emerald-500 animate-spin" />}
                        {isPast && <Check size={14} className="text-emerald-500" />}
                      </div>
                      <div className="h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
                        <motion.div 
                          initial={{ width: 0 }}
                          animate={{ width: isPast ? "100%" : isActive ? "50%" : 0 }}
                          transition={isActive ? { duration: stage.duration / 1000, ease: "linear" } : { duration: 0.2 }}
                          className={cn(
                            "h-full rounded-full",
                            isPast ? "bg-emerald-500" : "bg-emerald-600"
                          )}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>

              {evalStageIndex >= EVALUATION_STAGES.length && (
                <motion.div 
                  initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} 
                  className="mt-6 bg-emerald-50 text-emerald-700 p-3 rounded-lg border border-emerald-100 flex items-center justify-center gap-2 font-medium text-sm text-center"
                >
                  <Sparkles size={16} /> Evaluation Complete! Redirecting...
                </motion.div>
              )}
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { RefreshCw, ExternalLink } from 'lucide-react';
import { cn } from '../utils/utils';

const API_BASE = '/api';

function formatDate(iso) {
  try {
    return new Date(iso).toLocaleString();
  } catch (_) {
    return iso || '';
  }
}

export default function SubmissionsPage() {
  const [searchParams] = useSearchParams();
  const q = String(searchParams.get('q') || '').trim().toLowerCase();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [refreshTick, setRefreshTick] = useState(0);

  // Demo/student dashboard hardcodes student_id=1 today; mirror it here.
  const studentId = 1;

  useEffect(() => {
    let cancelled = false;
    const run = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await fetch(`${API_BASE}/submissions?student_id=${studentId}&limit=50`);
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Failed to load submissions');
        if (!cancelled) setItems(Array.isArray(data) ? data : data.items || []);
      } catch (e) {
        if (!cancelled) setError(e.message);
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    run();
    return () => {
      cancelled = true;
    };
  }, [refreshTick]);

  const stats = useMemo(() => {
    const total = items.length;
    const byStatus = items.reduce((acc, s) => {
      const key = s.status || 'unknown';
      acc[key] = (acc[key] || 0) + 1;
      return acc;
    }, {});
    return { total, byStatus };
  }, [items]);

  const filteredItems = useMemo(() => {
    if (!q) return items;
    return items.filter((s) => {
      const id = String(s?.id || '');
      const status = String(s?.status || '').toLowerCase();
      const title = String(s?.Question?.title || '').toLowerCase();
      return id.includes(q) || status.includes(q) || title.includes(q);
    });
  }, [items, q]);

  return (
    <div className="max-w-7xl mx-auto h-full flex flex-col gap-6 pb-12">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 tracking-tight">My Submissions</h1>
          <p className="text-sm text-gray-500 mt-1">Recent evaluations for your account.</p>
        </div>
        <button
          onClick={() => setRefreshTick(t => t + 1)}
          className="px-4 py-2 rounded-lg border border-gray-200 bg-white hover:bg-gray-50 text-gray-700 text-sm font-semibold flex items-center gap-2"
        >
          <RefreshCw size={16} /> Refresh
        </button>
      </div>

      {q && (
        <div className="text-sm text-gray-600">
          Showing results for <span className="font-mono bg-gray-100 px-2 py-0.5 rounded">{q}</span>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
          <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Total</div>
          <div className="mt-2 text-3xl font-black text-gray-900">{stats.total}</div>
        </div>
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
          <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Completed</div>
          <div className="mt-2 text-3xl font-black text-emerald-600">{stats.byStatus.completed || 0}</div>
        </div>
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
          <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Failed</div>
          <div className="mt-2 text-3xl font-black text-red-600">{stats.byStatus.failed || 0}</div>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
          <h2 className="font-bold text-gray-900">Recent</h2>
          {loading && <span className="text-sm text-gray-500">Loading…</span>}
        </div>

        {error ? (
          <div className="p-6 text-sm text-red-700 bg-red-50 border-t border-red-100">
            {error}
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead className="bg-gray-50 text-gray-600">
                <tr>
                  <th className="text-left font-semibold px-6 py-3">ID</th>
                  <th className="text-left font-semibold px-6 py-3">Status</th>
                  <th className="text-left font-semibold px-6 py-3">Score</th>
                  <th className="text-left font-semibold px-6 py-3">Created</th>
                  <th className="text-right font-semibold px-6 py-3">Report</th>
                </tr>
              </thead>
              <tbody>
                {filteredItems.map((s) => (
                  <tr key={s.id} className="border-t border-gray-100 hover:bg-gray-50/60">
                    <td className="px-6 py-3 font-mono text-xs text-gray-700">{s.id}</td>
                    <td className="px-6 py-3">
                      <span
                        className={cn(
                          'px-2 py-1 rounded-md text-xs font-bold',
                          s.status === 'completed' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' :
                          s.status === 'running' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' :
                          s.status === 'pending' ? 'bg-amber-50 text-amber-700 border border-amber-100' :
                          s.status === 'failed' ? 'bg-red-50 text-red-700 border border-red-100' :
                          'bg-gray-50 text-gray-700 border border-gray-100'
                        )}
                      >
                        {s.status || 'unknown'}
                      </span>
                    </td>
                    <td className="px-6 py-3 font-semibold text-gray-900">{s.total_score ?? '-'}</td>
                    <td className="px-6 py-3 text-gray-600">{formatDate(s.created_at)}</td>
                    <td className="px-6 py-3 text-right">
                      <Link
                        to={`/results/${s.id}`}
                        className="inline-flex items-center gap-2 text-emerald-700 hover:text-emerald-900 font-semibold"
                      >
                        View <ExternalLink size={14} />
                      </Link>
                    </td>
                  </tr>
                ))}
                {(!loading && filteredItems.length === 0) && (
                  <tr>
                    <td className="px-6 py-8 text-center text-gray-500" colSpan={5}>
                      {q
                        ? 'No matching submissions.'
                        : <>No submissions yet. Go to <Link to="/student" className="text-emerald-700 font-semibold">Practice Workspace</Link> and click Submit & Evaluate.</>}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Settings, BarChart2, Plus, GripVertical, Trash2, Code2, Users, FileSignature, Box, Loader2, ChevronDown, ChevronUp } from 'lucide-react';
import {
  Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement
} from 'chart.js';
import { Bar, Doughnut } from 'react-chartjs-2';
import CodeEditor from '../components/workspace/CodeEditor';
import { cn } from '../utils/utils';
import { useToast } from '../components/ui/use-toast';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement);

const DEFAULT_VIEWPORTS = [
  { name: 'desktop', width: 1366, height: 768 },
  { name: 'mobile', width: 390, height: 844 }
];

const DEFAULT_STARTER_HTML = "<div class='card'>\n  <!-- Start styling here -->\n</div>";

const DOM_ASSERTIONS = [
  { value: 'exists', label: 'Exists' },
  { value: 'count', label: 'Count Equals' },
  { value: 'textIncludes', label: 'Text Includes' },
  { value: 'textEquals', label: 'Text Equals' },
  { value: 'hasClass', label: 'Has Class' },
  { value: 'attributeEquals', label: 'Attribute Equals' },
  { value: 'valueEquals', label: 'Input Value Equals' },
  { value: 'alertCalled', label: 'Alert Called' },
  { value: 'alertIncludes', label: 'Alert Includes Text' }
];

const INTERACTION_ACTIONS = [
  { value: 'click', label: 'Click' },
  { value: 'hover', label: 'Hover' },
  { value: 'type', label: 'Type' },
  { value: 'scroll', label: 'Scroll Into View' },
  { value: 'keypress', label: 'Key Press' },
  { value: 'focus', label: 'Focus' },
  { value: 'select', label: 'Select Option' },
  { value: 'check', label: 'Check' },
  { value: 'uncheck', label: 'Uncheck' },
  { value: 'wait', label: 'Wait' },
  { value: 'waitForSelector', label: 'Wait For Selector' }
];

const assertionNeedsExpected = (assertion) => new Set([
  'count',
  'textIncludes',
  'textEquals',
  'hasClass',
  'attributeEquals',
  'valueEquals',
  'alertIncludes'
]).has(assertion);

const assertionNeedsSelector = (assertion) => !new Set(['alertCalled', 'alertIncludes']).has(assertion);

const actionNeedsSelector = (action) => !new Set(['keypress', 'wait']).has(action);
const actionNeedsValue = (action) => new Set(['type', 'select', 'wait']).has(action);
const actionNeedsKey = (action) => action === 'keypress';

function parseExpectedValue(input) {
  if (typeof input !== 'string') return input;
  const v = input.trim();
  if (!v) return '';
  if ((v.startsWith('[') && v.endsWith(']')) || (v.startsWith('{') && v.endsWith('}'))) {
    try {
      return JSON.parse(v);
    } catch (_) {
      return v;
    }
  }
  return v;
}

export default function TrainerPanel({ initialTab = 'builder', embedded = false } = {}) {
  const [activeTab, setActiveTab] = useState(() => (initialTab || 'builder'));
  const { toast } = useToast();

  const [questions, setQuestions] = useState([]);
  const [selectedQuestionId, setSelectedQuestionId] = useState(null);
  const [questionsLoading, setQuestionsLoading] = useState(true);
  const [creatingQuestion, setCreatingQuestion] = useState(false);
  const [newQuestionTitle, setNewQuestionTitle] = useState('');
  const [newQuestionDescription, setNewQuestionDescription] = useState('');
  const addQuestionRef = useRef(null);
  const [showAddQuestion, setShowAddQuestion] = useState(false);

  const [draftLoading, setDraftLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [baselineBusy, setBaselineBusy] = useState(false);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [allowedLibraries, setAllowedLibraries] = useState([]);
  const [starterHtml, setStarterHtml] = useState(DEFAULT_STARTER_HTML);
  const [starterCss, setStarterCss] = useState('');
  const [starterJs, setStarterJs] = useState('');
  const [showStarterEditor, setShowStarterEditor] = useState(false);
  const [showSpecJson, setShowSpecJson] = useState(false);

  useEffect(() => {
    if (!initialTab) return;
    setActiveTab(initialTab);
  }, [initialTab]);

  const [specBase, setSpecBase] = useState({ version: '1.0', viewports: DEFAULT_VIEWPORTS, tests: { dom: [], css: [], interactions: [] } });
  const nextTestIdRef = useRef(3);

  const [tests, setTests] = useState([
    { id: 1, type: 'dom', target: '.card', assertion: 'exists', weight: 10 },
    { id: 2, type: 'css', target: '.card', property: 'display', value: 'flex', weight: 20 }
  ]);
  const [interactionSteps, setInteractionSteps] = useState([]);
  const nextInteractionIdRef = useRef(1);

  const specJson = useMemo(() => {
    const base = specBase && typeof specBase === 'object' ? specBase : {};
    const viewports = Array.isArray(base.viewports) && base.viewports.length > 0 ? base.viewports : DEFAULT_VIEWPORTS;

    const baseTests = base.tests && typeof base.tests === 'object' ? base.tests : {};
    const nextTests = { ...baseTests };
    const dom = [];
    const css = [];

    tests.forEach((t) => {
      const raw = t._raw && typeof t._raw === 'object' ? t._raw : {};
      if (t.type === 'css') {
        if (t.property === 'ruleExists') {
          css.push({
            ...raw,
            testType: 'ruleExists',
            selectorContains: (t.value ?? t.target ?? '').toString(),
            selector: raw.selector || t.target || '',
          });
        } else {
          css.push({
            ...raw,
            selector: t.target || '',
            property: t.property || '',
            expected: parseExpectedValue(t.value ?? ''),
            matcher: raw.matcher || 'equals'
          });
        }
      } else {
        const nextDomTest = {
          ...raw,
          assertion: t.assertion || 'exists'
        };

        if (assertionNeedsSelector(t.assertion)) {
          nextDomTest.selector = t.target || '';
        } else {
          delete nextDomTest.selector;
        }

        if (assertionNeedsExpected(t.assertion)) {
          nextDomTest.expected = parseExpectedValue(t.value ?? '');
        } else {
          delete nextDomTest.expected;
        }

        if (t.assertion === 'attributeEquals') {
          nextDomTest.attribute = t.attribute || '';
        } else {
          delete nextDomTest.attribute;
        }

        dom.push(nextDomTest);
      }
    });

    nextTests.dom = dom;
    nextTests.css = css;
    nextTests.interactions = interactionSteps.map((step) => {
      const nextStep = {
        action: step.action || 'click',
        delay: Number(step.delay) >= 0 ? Number(step.delay) : 50
      };

      if (actionNeedsSelector(step.action)) nextStep.selector = step.selector || '';
      if (actionNeedsValue(step.action)) nextStep.value = step.value ?? '';
      if (actionNeedsKey(step.action)) nextStep.key = step.key || '';
      if (step.waitForVisible && actionNeedsSelector(step.action)) nextStep.waitForVisible = true;
      if (step.clear && step.action === 'type') nextStep.clear = true;

      return nextStep;
    });

    return { ...base, version: base.version || '1.0', viewports, tests: nextTests };
  }, [interactionSteps, specBase, tests]);

  const generateBaseline = async () => {
    if (!selectedQuestionId) return;
    setBaselineBusy(true);
    try {
      const res = await fetch(`/api/questions/${selectedQuestionId}/baseline`, { method: 'POST' });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Baseline generation failed');
      toast({
        title: 'Baseline Queued',
        description: `Question ${data.question_id} baseline v${data.version} queued (job: ${data.job_id || 'n/a'}).`
      });
    } catch (e) {
      toast({ title: 'Baseline Failed', description: e?.message || 'Could not queue baseline.', variant: 'destructive' });
    } finally {
      setBaselineBusy(false);
    }
  };

  useEffect(() => {
    let cancelled = false;

    async function loadQuestions() {
      setQuestionsLoading(true);
      try {
        const res = await fetch('/api/questions');
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.error || 'Failed to load questions');
        if (cancelled) return;
        const qs = Array.isArray(data.questions) ? data.questions : [];
        setQuestions(qs);
        if (qs.length > 0) {
          setSelectedQuestionId((prev) => (prev == null ? qs[0].id : prev));
        }
      } catch (e) {
        toast({ title: 'Load Failed', description: e?.message || 'Could not load questions.', variant: 'destructive' });
      } finally {
        if (!cancelled) setQuestionsLoading(false);
      }
    }

    loadQuestions();
    return () => { cancelled = true; };
  }, [toast]);

  useEffect(() => {
    let cancelled = false;

    async function loadDraft() {
      if (!selectedQuestionId) return;
      setDraftLoading(true);
      try {
        const res = await fetch(`/api/trainer/questions/${selectedQuestionId}/draft`);
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.error || 'Failed to load draft');

        if (cancelled) return;

        const q = data.question || {};
        const files = Array.isArray(data.files) ? data.files : [];
        const spec = data.testSpec && typeof data.testSpec === 'object' ? data.testSpec : null;

        setTitle(typeof q.title === 'string' ? q.title : '');
        setDescription(typeof q.description === 'string' ? q.description : '');
        setAllowedLibraries(Array.isArray(q.allowed_libraries) ? q.allowed_libraries : []);

        setStarterHtml(files.find((f) => f.type === 'html')?.content ?? DEFAULT_STARTER_HTML);
        setStarterCss(files.find((f) => f.type === 'css')?.content ?? '');
        setStarterJs(files.find((f) => f.type === 'js')?.content ?? '');

        const base = spec || { version: '1.0', viewports: DEFAULT_VIEWPORTS, tests: { dom: [], css: [], interactions: [] } };
        setSpecBase(base);

        const domSpec = Array.isArray(base?.tests?.dom) ? base.tests.dom : [];
        const cssSpec = Array.isArray(base?.tests?.css) ? base.tests.css : [];
        const interactionSpec = Array.isArray(base?.tests?.interactions) ? base.tests.interactions : [];

        const mapped = [];
        domSpec.forEach((t, idx) => {
          const expected = t?.expected;
          mapped.push({
            id: idx + 1,
            type: 'dom',
            target: t?.selector || '',
            assertion: t?.assertion || 'exists',
            attribute: t?.attribute || '',
            value: Array.isArray(expected) ? JSON.stringify(expected) : (expected ?? '').toString(),
            weight: 10,
            _raw: t
          });
        });
        cssSpec.forEach((t, idx) => {
          const id = mapped.length + idx + 1;
          if (t?.testType === 'ruleExists') {
            mapped.push({
              id,
              type: 'css',
              target: t?.selector || '',
              property: 'ruleExists',
              value: t?.selectorContains || t?.selector || '',
              weight: 10,
              _raw: t
            });
          } else {
            const expected = t?.expected;
            mapped.push({
              id,
              type: 'css',
              target: t?.selector || '',
              property: t?.property || '',
              value: Array.isArray(expected) ? JSON.stringify(expected) : (expected ?? '').toString(),
              weight: 10,
              _raw: t
            });
          }
        });

        if (mapped.length > 0) {
          setTests(mapped);
          nextTestIdRef.current = mapped.length + 1;
        } else {
          setTests([
            { id: 1, type: 'dom', target: '.card', assertion: 'exists', weight: 10 },
            { id: 2, type: 'css', target: '.card', property: 'display', value: 'flex', weight: 20 }
          ]);
          nextTestIdRef.current = 3;
        }

        const mappedInteractions = interactionSpec.map((step, idx) => ({
          id: idx + 1,
          action: step?.action || 'click',
          selector: step?.selector || '',
          value: step?.value ?? '',
          key: step?.key || '',
          delay: Number(step?.delay) >= 0 ? Number(step.delay) : 50,
          waitForVisible: Boolean(step?.waitForVisible),
          clear: Boolean(step?.clear)
        }));
        setInteractionSteps(mappedInteractions);
        nextInteractionIdRef.current = mappedInteractions.length + 1;
      } catch (e) {
        toast({
          title: 'Draft Load Failed',
          description: e?.message || 'Could not load question draft.',
          variant: 'destructive'
        });
      } finally {
        if (!cancelled) setDraftLoading(false);
      }
    }

    loadDraft();
    return () => {
      cancelled = true;
    };
  }, [selectedQuestionId, toast]);

  const updateTest = (id, patch) => {
    setTests((prev) => prev.map((t) => (t.id === id ? { ...t, ...patch } : t)));
  };

  const removeTest = (id) => {
    setTests((prev) => prev.filter((t) => t.id !== id));
  };

  const addTest = () => {
    const id = nextTestIdRef.current++;
    setTests((prev) => [
      ...prev,
      { id, type: 'dom', target: '', assertion: 'exists', weight: 10 }
    ]);
  };

  const updateInteractionStep = (id, patch) => {
    setInteractionSteps((prev) => prev.map((step) => (step.id === id ? { ...step, ...patch } : step)));
  };

  const removeInteractionStep = (id) => {
    setInteractionSteps((prev) => prev.filter((step) => step.id !== id));
  };

  const addInteractionStep = () => {
    const id = nextInteractionIdRef.current++;
    setInteractionSteps((prev) => [
      ...prev,
      {
        id,
        action: 'click',
        selector: '',
        value: '',
        key: 'Enter',
        delay: 50,
        waitForVisible: true,
        clear: false
      }
    ]);
  };

  const handleSaveDraft = async () => {
    if (!selectedQuestionId) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/trainer/questions/${selectedQuestionId}/draft`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title,
          description,
          allowed_libraries: allowedLibraries,
          starter_html: starterHtml,
          starter_css: starterCss,
          starter_js: starterJs,
          spec_json: specJson
        })
      });

      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Failed to save draft');

      toast({
        title: data?.baseline?.queued ? 'Draft Saved & Queued' : 'Draft Saved',
        description: data?.baseline?.queued
          ? `Your changes were saved and baseline v${data.baseline.version} was queued automatically.`
          : 'Your changes have been saved.'
      });
    } catch (e) {
      toast({
        title: 'Save Failed',
        description: e?.message || 'Could not save draft.',
        variant: 'destructive'
      });
    } finally {
      setSaving(false);
    }
  };

  const handleCreateQuestion = async () => {
    const t = newQuestionTitle.trim();
    if (!t) {
      toast({ title: 'Title Required', description: 'Please enter a question title.', variant: 'destructive' });
      return;
    }
    setCreatingQuestion(true);
    try {
      const res = await fetch('/api/trainer/questions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: t, description: newQuestionDescription })
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Failed to create question');
      const q = data.question;
      toast({
        title: data?.baseline?.queued ? 'Question Created & Queued' : 'Question Created',
        description: data?.baseline?.queued
          ? `New question is ready to edit and baseline v${data.baseline.version} is generating now.`
          : 'New question is ready to edit.'
      });
      setNewQuestionTitle('');
      setNewQuestionDescription('');
      // Refresh list and select the new question.
      const listRes = await fetch('/api/questions');
      const listData = await listRes.json().catch(() => ({}));
      const qs = Array.isArray(listData.questions) ? listData.questions : [];
      setQuestions(qs);
      if (q?.id) setSelectedQuestionId(q.id);
    } catch (e) {
      toast({ title: 'Create Failed', description: e?.message || 'Could not create question.', variant: 'destructive' });
    } finally {
      setCreatingQuestion(false);
    }
  };

  // Mock Analytics Data
  const analyticsData = {
    avgScore: 78.5,
    avgExecution: '1.2s',
    totalSubmissions: 342,
    passRate: '64%',
    scoreHistogram: [12, 25, 68, 142, 95],
    failedTests: [
      { test: '.profile-card display:flex', count: 124 },
      { test: 'button:hover background-color', count: 89 },
      { test: '.avatar border-radius', count: 45 }
    ]
  };

  return (
    <div className={embedded ? "w-full flex flex-col gap-6" : "max-w-7xl mx-auto h-full flex flex-col gap-6 pb-12"}>

      {/* Header & Tabs */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 tracking-tight">{embedded ? 'Teacher Tools' : 'Trainer Dashboard'}</h1>
          <p className="text-sm text-gray-500 mt-1">Manage assessment questions, test specs, and analyze cohort performance.</p>
        </div>

        {activeTab === 'builder' && (
          <button
            onClick={generateBaseline}
            disabled={baselineBusy || !selectedQuestionId}
            className="px-4 py-2 rounded-lg border border-gray-200 bg-white hover:bg-gray-50 text-gray-700 text-sm font-semibold flex items-center gap-2 disabled:opacity-60 disabled:cursor-not-allowed"
            title="Generate baseline screenshots from the reference solution (FR-2)"
          >
            {baselineBusy ? <Loader2 size={16} className="animate-spin" /> : <Box size={16} />}
            Generate Baseline
          </button>
        )}

        <div className="flex bg-gray-100/80 p-1.5 rounded-xl border border-gray-200/60">
          <button 
            onClick={() => setActiveTab('builder')}
            className={cn(
              "px-5 py-2.5 rounded-lg text-sm font-semibold transition-all flex items-center gap-2",
              activeTab === 'builder' ? "bg-white text-emerald-700 shadow-sm" : "text-gray-600 hover:text-gray-900"
            )}
          >
            <Settings size={16} /> Content Builder
          </button>
          <button 
            onClick={() => setActiveTab('analytics')}
            className={cn(
              "px-5 py-2.5 rounded-lg text-sm font-semibold transition-all flex items-center gap-2",
              activeTab === 'analytics' ? "bg-white text-emerald-700 shadow-sm" : "text-gray-600 hover:text-gray-900"
            )}
          >
            <BarChart2 size={16} /> Cohort Analytics
          </button>
        </div>
      </div>

      {activeTab === 'builder' && (
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
          {/* Question List */}
          <div className="xl:col-span-3 bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col">
            <div className="bg-gray-50/50 px-5 py-3 border-b border-gray-100 flex items-center justify-between gap-3">
              <h2 className="font-bold text-gray-900">Questions</h2>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => {
                    setShowAddQuestion(true);
                    setTimeout(() => addQuestionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' }), 0);
                  }}
                  className="inline-flex items-center gap-1.5 text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-lg hover:bg-emerald-100 transition-colors"
                >
                  <Plus size={14} /> Add
                </button>
                {questionsLoading && <Loader2 size={16} className="animate-spin text-gray-400" />}
              </div>
            </div>
            <div className="p-4 flex-1 overflow-y-auto">
              {questions.length === 0 && !questionsLoading ? (
                <div className="text-sm text-gray-500">No questions yet.</div>
              ) : (
                <div className="space-y-2">
                  {questions.map((q) => (
                    <button
                      key={q.id}
                      onClick={() => setSelectedQuestionId(q.id)}
                      className={cn(
                        "w-full text-left px-3 py-2 rounded-xl border transition-colors",
                        selectedQuestionId === q.id
                          ? "border-emerald-200 bg-emerald-50 text-emerald-900"
                          : "border-gray-100 bg-white hover:bg-gray-50 text-gray-800"
                      )}
                    >
                      <div className="text-sm font-semibold truncate">{q.title}</div>
                      <div className="text-xs text-gray-500 truncate">ID: {q.id}</div>
                    </button>
                  ))}
                </div>
              )}
            </div>
            <div ref={addQuestionRef} className="border-t border-gray-100 bg-gray-50/30">
              <button
                type="button"
                onClick={() => setShowAddQuestion((v) => !v)}
                className="w-full px-4 py-3 flex items-center justify-between text-sm font-semibold text-gray-800 hover:bg-gray-50 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <Plus size={16} className="text-emerald-600" />
                  Add Question
                </span>
                {showAddQuestion ? <ChevronUp size={18} className="text-gray-400" /> : <ChevronDown size={18} className="text-gray-400" />}
              </button>

              {showAddQuestion && (
              <div className="p-4 pt-2 space-y-3">
              <div>
                <label className="block text-xs font-semibold text-gray-600 uppercase tracking-widest mb-1.5">New Question Title</label>
                <input
                  value={newQuestionTitle}
                  onChange={(e) => setNewQuestionTitle(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-emerald-100 focus:border-emerald-400"
